-- p4_24 — the specimen report page: /report/example/index.html
--
-- Owner decision 2026-07-28: publish a specimen so the six card links on
-- /report.html that promise "See an example" / "View specimen report" stop
-- promising something that does not exist. Source is an EXISTING report — the
-- owner's own vet price-comparison idea, ord_1785090638951163875, bought and
-- delivered 2026-07-26 — refreshed later once the current formatting has run on
-- a real order.
--
-- PROVENANCE, and why this specimen is honest:
--   * The analysis is reproduced IN FULL and verbatim. Nothing added, removed or
--     reworded.
--   * TWO typographical corrections applied, both faults in our own renderer at
--     the time and both since fixed in the software: a doubled full stop, and a
--     score line that read "out of 5 —" with the number missing. Publishing our
--     own formatting bugs would misrepresent the product in the other direction.
--   * The idea is the OWNER'S OWN submission. Owner ruled explicitly that the
--     28 July test order's idea must not be used, and no customer's idea will be
--     published. The page says both of these things in its own words.
--
-- URL: /report/example/index.html — probed 404 first. The tool reserves its
-- routes by EXACT match, so /report is the tool and /report/example/... is
-- static; no collision.
--
-- page_type='content' deliberately: 'guide' or 'tool' would make it self-list in
-- those hubs, which it is not.  in_header/in_footer false — it is reached from
-- the report page, not from the nav.

\set site '1244516d-014d-421c-88c6-090bb1e9552a'

BEGIN;

INSERT INTO pages (site_id, name, url, title, page_type, nav_label, nav_order,
                   in_header, in_footer, meta_description, status, build_status)
VALUES (:'site', 'report-example', '/report/example/index.html',
        'An example report, in full',
        'content', 'Example report', 95, false, false,
        'A complete example of the £29 idea.uk Verified Idea Report: the assessment, the evidence behind each judgement, sources you can check, and the further ideas found around the idea.',
        'active', 'pending')
ON CONFLICT DO NOTHING;

-- Sections. slot_name is set from the component's own `function` below, never
-- typed by hand: a NULL or mistyped slot_name misses schemas[s.slotName], takes
-- the "carrying stored HTML" branch, and on a NEW page the stored HTML is empty
-- — so the job reports COMPLETED and the page does not exist (RUNBOOK TRAP 1).
INSERT INTO page_components (page_id, component_id, position, content_data, build_status)
SELECT p.id, '23f95f00-f293-466e-b43a-81791ea0fc6c', 1, $j${"headline": "An example report, in full", "subheadline": "This is exactly what a \u00a329 Verified Idea Report looks like \u2014 the assessment of the idea that was sent in, the evidence behind each judgement, sources you can check, and the further ideas we found around it.", "cta_text": "Request your own report", "cta_url": "/report.html#request-a-report"}$j$::jsonb, 'pending'
FROM pages p WHERE p.site_id = :'site' AND p.name = 'report-example'
ON CONFLICT DO NOTHING;

INSERT INTO page_components (page_id, component_id, position, content_data, build_status)
SELECT p.id, '8d81e665-3ee0-443d-a873-690268c15fbb', 2, $j${"content": "<p class=\"note\"><strong>This is a real report, reproduced in full.</strong> It was bought and delivered on 26 July 2026 for \u00a329. Nothing has been added, removed or reworded \u2014 the only changes are two typographical corrections (a doubled full stop and a mis-rendered score line), both of which were faults in our formatting at the time and are fixed in the software now.</p>\n<p class=\"note\">The idea it assesses was submitted by us, not by a customer. We would not publish a customer's idea.</p>\n<hr>\n<p>This report is from idea.uk, about what you sent us: A price-transparency comparison service for UK veterinary practices: owners get an upfront estimate for routine treatments (vaccinations, neutering, dental) before they book, rather than finding out at the counter. First we assess the idea you submitted \u2014 the problem it addresses, the evidence of demand, who else is out there, where it is defensible and where it is exposed, and a specific next step. Then we go looking for further ideas around it, check each against what already exists and whether people would actually pay, and set out the ones worth pursuing \u2014 and the ones we set aside, and why. We use AI to research and draft this report, with live web searches for the checking; a person reviews it before it is sent. Where a finding rests on something we read, the sources are listed under it so you can check them yourself.</p>\n<h2>Your idea, assessed</h2>\n<p class=\"reading\"><em>You want to build a website where UK pet owners can see and compare upfront prices for routine treatments (vaccinations, neutering, dental) at different vet practices before they book, and where open, independent practices can stand out by being clear about price.</em></p>\n<h3>The problem, and the evidence people have it</h3>\n<p>The problem is real and well documented, not just plausible. Pet owners regularly get bills far bigger than they expected. The UK competition watchdog (the Competition and Markets Authority, the government body that checks whether markets treat customers fairly) launched a review after finding vet fees were rising faster than other everyday costs during the cost-of-living squeeze. The consumer group Which? told the watchdog that owners can face very large, shock bills. So the pain you are pointing at genuinely exists.</p>\n<h3>Signs of real demand</h3>\n<p>Demand for this information is strong. A public petition asking for fairer, clearer vet bills passed more than 80,000 signatures. One widely reported owner was &#x27;gobsmacked&#x27; at a \u00a31,500 dental bill for her pug. News coverage across the BBC, ITV and others has been heavy, and lots of people already type searches like &#x27;cheapest vet near me&#x27; into Google. The watchdog also received a record number of responses to its review. In short: plenty of people want to know prices before they commit.</p>\n<h3>Who else is addressing it, and how</h3>\n<p>This space is already crowded, and that is the biggest single fact you need to sit with. VetHelpDirect has been doing vet price comparison since 2006 and lists prices for around 1,600 practices. Rightvet claims data on 5,702 UK practices; WhatTheVet claims 5,500-plus. Several more launched in 2026 on the back of the reforms, including FairVet, VetCostCompare, ClearVet, WisePet and VetCost. Most importantly, the government&#x27;s own reforms include an enhanced official &#x27;Find a Vet&#x27; service and a new price comparison website so owners can find the lowest prices. That is a free, government-backed competitor doing the exact thing you propose.</p>\n<h3>What people would use instead today</h3>\n<p>Someone who wants this today already has easy, free options. They can ring two or three local practices and ask the price (many will tell you over the phone). They can look at practice websites. They can use one of the free comparison sites named above. They can ask in a local pet Facebook group. And from late 2026 the law will force every practice to publish a clear price list for common treatments on its own website, so a simple web search will increasingly surface the prices for free.</p>\n<h3>Where it is defensible</h3>\n<p>As submitted, there is very little here that is hard to copy. The thing that would normally be your protected asset \u2014 a big collection of vet prices you gathered by hand \u2014 is exactly the thing the new rules are about to make free and public. The only places you could be defensible are narrow: genuine, trusted relationships with a specific group of independent practices in one area; or a clearly better way to compare a whole treatment &#x27;like for like&#x27; (the full cost of a neuter including consultation, medicine and follow-up, not one headline fee) that the free tools handle badly. Neither of those is in the idea as written.</p>\n<h3>Where it is exposed</h3>\n<p>Very exposed, on several sides at once. First, your core asset (collected prices) is being turned into free, published-by-law information. Second, an official government comparison and &#x27;Find a Vet&#x27; service is being introduced \u2014 a huge free rival. Third, a dozen private sites already exist, some better funded and with years of head start. Fourth, independent vets have little reason to pay to be listed when they will soon be legally required to publish their prices anyway, so your route to actually getting paid is unclear. Fifth, you are one person, part-time, up against all of that. This is the honest weak point: the idea is a comparison directory in a market that is about to be flooded with free, official comparison.</p>\n<h3>A considered next step</h3>\n<p>Do a cheap, one-week test of the weakest link before building anything. Pick a single town. By hand, collect the prices for three routine treatments (a vaccination, a neuter, and a dental) from 15 to 20 local practices \u2014 most are already on their websites or given over the phone. Put them in one simple comparison table on the rough landing page you already have, with a box where an owner can leave an email to &#x27;get told when your area is covered&#x27;. Then spend \u00a350 to \u00a3100 on local Facebook ads, or post in a few local pet groups, and count how many owners actually look and leave an email. At the same time, phone 8 to 10 independent practices and ask one blunt question: would you pay around \u00a320 to \u00a330 a month to stand out on a price-and-openness site? If owners shrug and vets won&#x27;t pay, that is your answer \u2014 stop before you write a line of software.</p>\n<h3>Check it yourself</h3>\n<ul class=\"sources\">\n<li><a href=\"https://feeds.bbci.co.uk/news/business-66733077\" rel=\"nofollow noopener\" target=\"_blank\">Vet prices review over fears pet owners are being overcharged (BBC)</a></li>\n<li><a href=\"https://feeds.bbci.co.uk/news/articles/cqeedg5274mo\" rel=\"nofollow noopener\" target=\"_blank\">Pet owner&#x27;s vet fees petition passes 80k signatures (BBC)</a></li>\n<li><a href=\"https://www.itv.com/news/2026-03-24/greater-transparency-for-pet-owners-as-uk-vets-forced-to-publish-price-lists\" rel=\"nofollow noopener\" target=\"_blank\">Greater transparency for pet owners as UK vets forced to publish price lists (ITV News)</a></li>\n<li><a href=\"https://www.aol.com/news/vet-welcomes-common-sense-crackdown-151146511.html\" rel=\"nofollow noopener\" target=\"_blank\">Vet welcomes &#x27;common sense&#x27; crackdown on fees (AOL / The Independent)</a></li>\n<li><a href=\"https://www.petgazette.biz/238558-government-unveils-veterinary-sector-reforms/\" rel=\"nofollow noopener\" target=\"_blank\">Government unveils veterinary sector reforms (Pet Gazette)</a></li>\n<li><a href=\"https://vethelpdirect.com/uk-vet-price-comparison/\" rel=\"nofollow noopener\" target=\"_blank\">Vet Prices Comparison UK (Vet Help Direct)</a></li>\n<li><a href=\"https://www.rightvet.uk/\" rel=\"nofollow noopener\" target=\"_blank\">Rightvet: Compare Vet Prices &amp; Ownership Across the UK</a></li>\n<li><a href=\"https://fairvet.co.uk/\" rel=\"nofollow noopener\" target=\"_blank\">FairVet - Compare UK Vet Prices (Launching 2026)</a></li>\n</ul>\n<h2>Who it&#x27;s for</h2>\n<p>UK independent vet practices (small, owner-run clinics that are not part of a big corporate chain)</p>\n<h2>Why they&#x27;d pay</h2>\n<p>Pet owners will happily use a free price-comparison site but almost never pay for one, because they only need it once or twice a year when a bill surprises them. Independent vet practices, on the other hand, lose real money to empty appointment slots and to owners who leave over price shocks, so a practice that believes clear pricing brings in bookings would pay a modest monthly fee to be listed and to keep its prices up to date.</p>\n<h2>Further ideas worth pursuing (best first)</h2>\n<h3>1) One-tap estimate builder for the front desk <span class=\"badge\">worth testing now</span></h3>\n<p>It uses the practice&#x27;s real prices and its own rules for add-ons, so the estimate matches what the vet will actually charge, not a made-up average.</p>\n<p><strong>What it&#x27;s built on:</strong> The practice&#x27;s price list plus its notes on what a typical neutering or dental job really involves (bloods, medication, extra time), using A form the receptionist fills in about the pet (weight, age, breed) that returns a written, itemised estimate ready to hand or email to the owner.</p>\n<p><strong>What we found:</strong> I checked whether UK vets are under real pressure to give prices upfront, and whether tools like this already exist. The competition regulator&#x27;s recent review of vets is pushing practices to show clear costs before treatment, so the demand is real; simple estimate features do already live inside some practice software, but a quick front-desk tool built on a practice&#x27;s own real prices and add-on rules is still a fair gap.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 3, people will pay 3, easy to build 4, reusable elsewhere 3, built to last 4 (17 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 3/5 (moderate \u2014 show your sources; insurance for handling personal data is recommended)</p>\n<p><strong>A cheap first test:</strong> Write a one-page description of the tool, name a monthly price (say \u00a349\u2013\u00a399), and send it directly to 20 practice managers via LinkedIn or a vets&#x27; Facebook group; count how many ask to see a demo or say &#x27;yes, we&#x27;d pay that&#x27; \u2014 three genuine expressions of intent is enough to proceed.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://britbrief.co.uk/business/regulations/veterinary-industry-overhaul-as-cma-exposes-price-gouging.html\" rel=\"nofollow noopener\" target=\"_blank\">Veterinary Industry Faces Major Overhaul as CMA Exposes Price Gouging - British Brief</a></li>\n<li><a href=\"https://todaysveterinarybusiness.com/uk-cma-ruling-veterinary-costs/\" rel=\"nofollow noopener\" target=\"_blank\">What the UK&#x27;s CMA Ruling Means for US Veterinary Practices - Today&#x27;s Veterinary Business</a></li>\n<li><a href=\"https://www.capterra.co.uk/directory/30617/veterinary/software\" rel=\"nofollow noopener\" target=\"_blank\">Veterinary Software - Price Comparison &amp; Reviews - Capterra UK</a></li>\n</ul>\n<p>If you&#x27;d like us to help turn any of these ideas into a working tool \u2014 or you have any questions about this report \u2014 just email us at idea-uk@leopardess.uk.</p>\n<p>idea.uk finds and tests AI product ideas for your business, so you can spend your time building the ones most likely to pay off.</p>\n<hr>\n<p class=\"note\">Your report would be about <em>your</em> idea, researched the same way, with its own sources you can check. It costs \u00a329, a person reads it before it is sent, and if it turns up nothing worth acting on you get your money back.</p>"}$j$::jsonb, 'pending'
FROM pages p WHERE p.site_id = :'site' AND p.name = 'report-example'
ON CONFLICT DO NOTHING;

UPDATE page_components pc SET slot_name = cc.function
FROM content_components cc, pages p
WHERE cc.id = pc.component_id AND pc.page_id = p.id
  AND p.site_id = :'site' AND p.name = 'report-example';

COMMIT;

-- Every section must have a non-NULL slot_name and non-empty content_data, or
-- the rerender renders nothing and still reports success.
SELECT pc.position, pc.slot_name, cc.function,
       (pc.slot_name = cc.function) AS slot_ok,
       length(pc.content_data::text) AS data_len
FROM page_components pc
JOIN content_components cc ON cc.id = pc.component_id
JOIN pages p ON p.id = pc.page_id
WHERE p.site_id = :'site' AND p.name = 'report-example'
ORDER BY pc.position;
